create extension if not exists pgcrypto;
create table if not exists collections (id uuid primary key default gen_random_uuid(), handle text unique not null, title text, description_html text, seo_title text, seo_description text, source_id text, published boolean default true, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists products (id uuid primary key default gen_random_uuid(), handle text unique not null, title text not null, description_html text, vendor text, product_type text, status text, seo_title text, seo_description text, source_id text, published_at timestamptz, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists product_variants (id uuid primary key default gen_random_uuid(), product_id uuid not null references products(id) on delete cascade, sku text, barcode text, title text, option1 text, option2 text, option3 text, price numeric(12,2), compare_at_price numeric(12,2), inventory_quantity integer, source_id text, position integer, created_at timestamptz default now());
create index if not exists idx_variants_product on product_variants(product_id); create index if not exists idx_variants_sku on product_variants(sku);
create table if not exists product_media (id uuid primary key default gen_random_uuid(), product_id uuid not null references products(id) on delete cascade, source_url text not null, alt_text text, position integer, media_type text default 'image', source_id text);
create table if not exists product_collections (product_id uuid references products(id) on delete cascade, collection_id uuid references collections(id) on delete cascade, primary key(product_id, collection_id));
create table if not exists pages (id uuid primary key default gen_random_uuid(), handle text unique not null, title text not null, body_html text, seo_title text, seo_description text, published boolean default true, source_id text, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists blog_posts (id uuid primary key default gen_random_uuid(), blog_handle text, handle text not null, title text not null, body_html text, excerpt text, author text, tags text, seo_title text, seo_description text, published_at timestamptz, source_id text, created_at timestamptz default now(), unique(blog_handle, handle));
create table if not exists redirects (id uuid primary key default gen_random_uuid(), from_path text unique not null, to_path text not null, http_status integer not null default 301 check (http_status in (301,302,307,308)), source text default 'shopify');
create table if not exists url_migrations (id uuid primary key default gen_random_uuid(), content_type text, source_handle text, old_modularhome_path text, new_path text, action text, verified boolean default false, notes text);
